p = Path('tests/test_jianghe_prespend_repair.py')
text = p.read_text(encoding='utf-8')
marker = '\n\nif __name__ == "__main__":\n    unittest.main()\n'
if text.count(marker) != 1:
    raise SystemExit("focused repair test marker mismatch")
p.write_text(text.replace(marker, '\n\nclass RuntimeRepairTests(unittest.TestCase):\n    def test_same_intent_id_different_content_fails_closed(self):\n        from src.contract_semantics import PositionDirection\n        from src.intent import ConflictResolver, IntentAction, StrategyIntent\n\n        common = dict(\n            intent_id="same-id",\n            strategy_identity_id="strategy-v1",\n            instrument="cu",\n            concrete_contract_id="cu2403",\n            action=IntentAction.OPEN,\n            decision_at=NOW,\n            context_identity="context-v1",\n            direction=PositionDirection.LONG,\n            quantity=Decimal("1"),\n        )\n        first = StrategyIntent(reason="first", **common)\n        changed = StrategyIntent(reason="changed", **common)\n        with self.assertRaises(ValueError):\n            ConflictResolver().resolve((first, changed))\n\n    def test_same_intent_id_same_full_content_remains_idempotent(self):\n        from src.contract_semantics import PositionDirection\n        from src.intent import ConflictResolver, IntentAction, StrategyIntent\n\n        intent = StrategyIntent(\n            intent_id="same-id",\n            strategy_identity_id="strategy-v1",\n            instrument="cu",\n            concrete_contract_id="cu2403",\n            action=IntentAction.OPEN,\n            decision_at=NOW,\n            context_identity="context-v1",\n            direction=PositionDirection.LONG,\n            quantity=Decimal("1"),\n            reason="same",\n        )\n        result = ConflictResolver().resolve((intent, intent))\n        self.assertEqual(len(result.resolutions), 1)\n\n    def test_trading_state_admission_precedes_oms_side_effect(self):\n        from types import SimpleNamespace\n        from src.shadow_runtime import ShadowRuntime\n\n        order = []\n        class Broker:\n            def drain_events(self):\n                return ("event",)\n        class State:\n            def apply_broker_event(self, event):\n                order.append("state")\n                return SimpleNamespace(applied=True)\n        class Oms:\n            def apply_broker_event(self, event):\n                order.append("oms")\n\n        runtime = object.__new__(ShadowRuntime)\n        runtime._broker = Broker()\n        runtime._state = State()\n        runtime._oms = Oms()\n        result = runtime.drain_and_apply_events()\n        self.assertEqual(len(result), 1)\n        self.assertEqual(order, ["state", "oms"])\n\n    def test_rejected_or_duplicate_event_never_mutates_oms(self):\n        from types import SimpleNamespace\n        from src.shadow_runtime import ShadowRuntime\n\n        calls = []\n        class Broker:\n            def drain_events(self):\n                return ("rejected", "duplicate")\n        class State:\n            def apply_broker_event(self, event):\n                calls.append(("state", event))\n                return SimpleNamespace(applied=False)\n        class Oms:\n            def apply_broker_event(self, event):\n                calls.append(("oms", event))\n\n        runtime = object.__new__(ShadowRuntime)\n        runtime._broker = Broker()\n        runtime._state = State()\n        runtime._oms = Oms()\n        result = runtime.drain_and_apply_events()\n        self.assertEqual(len(result), 2)\n        self.assertEqual(calls, [("state", "rejected"), ("state", "duplicate")])\n' + marker), encoding="utf-8")

